    window.TRANSLATIONS = T

    // Current language — set by the app on init
    window.appLanguage = window.appLanguage || 'de'

    // Lookup function
    window.t = function (key) {
        return (T[window.appLanguage] || T.de)[key] ?? (T.de[key] ?? key)
    }

    // Apply all [data-i18n] elements in the document
    window.applyI18n = function (lang) {
        if (lang) window.appLanguage = lang
        document.querySelectorAll('[data-i18n]').forEach(el => {
            const k = el.getAttribute('data-i18n')
            const v = window.t(k)
            if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {
                // handled via data-i18n-ph
            } else {
                el.textContent = v
            }
        })
        document.querySelectorAll('[data-i18n-title]').forEach(el => {
            el.title = window.t(el.getAttribute('data-i18n-title'))
        })
        document.querySelectorAll('[data-i18n-ph]').forEach(el => {
            el.placeholder = window.t(el.getAttribute('data-i18n-ph'))
        })
    }
